import { test, expect } from '@playwright/test';

test.describe('Login Spinner Visibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display spinner while login request is in progress', async ({ page }) => {
    // Intercept the login API call
    await page.route('**/api/auth/login', (route) => {
      route.abort('blockedbyclient');
    });

    // Get email input by label
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();
    await emailInput.fill('user@example.com');

    // Get password input by label
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toBeVisible();
    await passwordInput.fill('Password123');

    // Get login button by role
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();

    // Click login button
    await loginButton.click();

    // Wait for spinner to appear
    const spinner = page.getByRole('status', { name: /loading/i });
    await expect(spinner).toBeVisible();

    // Verify spinner has correct class
    await expect(spinner).toHaveClass(/spinner-active/);

    // Verify login button is disabled
    await expect(loginButton).toBeDisabled();

    // Verify spinner is visible
    await expect(spinner).toBeVisible();
  });

  test('should hide spinner and show error message on failed login', async ({ page }) => {
    // Intercept the login API call and return an error response
    await page.route('**/api/auth/login', (route) => {
      route.fulfill({
        status: 401,
        contentType: 'application/json',
        body: JSON.stringify({ error: 'Invalid credentials' }),
      });
    });

    // Get email input by label
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();
    await emailInput.fill('user@example.com');

    // Get password input by label
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toBeVisible();
    await passwordInput.fill('wrongpassword');

    // Get login button by role
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();

    // Click login button
    await loginButton.click();

    // Wait for spinner to appear
    const spinner = page.getByRole('status', { name: /loading/i });
    await expect(spinner).toBeVisible();

    // Wait for spinner to disappear
    await page.waitForTimeout(1000);

    // Verify spinner is no longer visible
    await expect(spinner).not.toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid credentials/i);
    await expect(errorMessage).toBeVisible();

    // Verify login button is enabled again
    await expect(loginButton).not.toBeDisabled();
  });
});
